import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Mail, MessageCircle, Globe, type LucideIcon } from "lucide-react"

import { cn } from "@/lib/utils"

// ── Types ──

export type SocialPlatform =
  | "github"
  | "twitter"
  | "x"
  | "linkedin"
  | "youtube"
  | "instagram"
  | "discord"
  | "bluesky"
  | "whatsapp"
  | "email"
  | "website"

export interface SocialLinkItem {
  platform: SocialPlatform
  href: string
  label?: string
}

export interface SocialLinksProps
  extends
    React.HTMLAttributes<HTMLElement>,
    VariantProps<typeof socialLinksVariants> {
  links: SocialLinkItem[]
  shape?: "circle" | "rounded" | "square"
  navLabel?: string
}

// ── Variants ──

export const socialLinksVariants = cva("flex items-center", {
  variants: {
    variant: {
      ghost: "text-muted-foreground hover:bg-muted hover:text-foreground",
      outline:
        "border border-border text-muted-foreground hover:border-foreground/20 hover:bg-muted hover:text-foreground",
      muted:
        "bg-muted/60 text-muted-foreground hover:bg-muted hover:text-foreground",
    },
    size: {
      sm: "size-7 [&_svg]:size-3.5",
      md: "size-8 [&_svg]:size-4",
      lg: "size-9 [&_svg]:size-4.5",
    },
    gap: {
      sm: "gap-1",
      md: "gap-1.5",
      lg: "gap-2",
    },
  },
  defaultVariants: {
    variant: "ghost",
    size: "md",
    gap: "md",
  },
})

// ── Helpers ──

