function BlueskyIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" {...props}>
      <path d="M12 10.8c-1.087-2.114-4.046-6.053-6.798-7.995C2.566 1.01 1.5 1.7 1.5 4.5c0 1.5.3 6.5 1.5 8 1.8 2.2 4.5 2.5 6 1.5-1.5 1.5-3.5 4-1 6.5 3 3 4-2 4-2s1 5 4 2c2.5-2.5.5-5-1-6.5 1.5 1 4.2.7 6-1.5 1.2-1.5 1.5-6.5 1.5-8 0-2.8-1.066-3.49-3.702-1.695C16.046 4.747 13.087 8.686 12 10.8z" />
    </svg>
  )
}

const PLATFORM_CONFIG: Record<
  SocialPlatform,
  {
    label: string
    icon: LucideIcon | React.ComponentType<React.SVGProps<SVGSVGElement>>
  }
> = {
  github: { label: "GitHub", icon: GithubIcon },
  twitter: { label: "X (Twitter)", icon: XIcon },
  x: { label: "X", icon: XIcon },
  linkedin: { label: "LinkedIn", icon: LinkedinIcon },
  youtube: { label: "YouTube", icon: YoutubeIcon },
  instagram: { label: "Instagram", icon: InstagramIcon },
  discord: { label: "Discord", icon: DiscordIcon },
  bluesky: { label: "Bluesky", icon: BlueskyIcon },
  whatsapp: { label: "WhatsApp", icon: MessageCircle },
  email: { label: "Email", icon: Mail },
  website: { label: "Website", icon: Globe },
}

const SHAPE_CLASSES = {
  circle: "rounded-full",
  rounded: "rounded-lg",
  square: "rounded-none",
}

// ── Component ──

export const SocialLinks = React.forwardRef<HTMLElement, SocialLinksProps>(
  (
    {
      links,
      variant = "ghost",
      size = "md",
      gap = "md",
      shape = "circle",
      navLabel = "Canais e redes sociais",
      className,
      ...props
    },
    ref
  ) => {
    return (
      <nav
        ref={ref}
        aria-label={navLabel}
        className={cn("flex items-center", className)}
        {...props}
      >
        <ul
          className={cn(
            "flex flex-wrap items-center",
            socialLinksVariants({ gap })
          )}
        >
          {links.map((item, index) => {
            const config = PLATFORM_CONFIG[item.platform]
            const Icon = config?.icon || Globe
            const label = item.label || config?.label || item.platform

            return (
              <li key={`${item.platform}-${index}`}>
                <a
                  href={item.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={label}
                  title={label}
                  className={cn(
                    "inline-flex items-center justify-center transition-colors outline-none",
                    "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                    socialLinksVariants({ variant, size }),
                    SHAPE_CLASSES[shape]
                  )}
                >
                  <Icon className="shrink-0" />
                </a>
              </li>
            )
          })}
        </ul>
      </nav>
    )
  }
)
SocialLinks.displayName = "SocialLinks"
